    const cap = window.matchMedia && window.matchMedia("(min-width: 901px)").matches ? 3 : 2;
    const need = Math.min(cap, shown * 0.95);
    return [BASE_RES, 2, 3].find((r) => r >= need && r >= BASE_RES) || cap;
